def _anchor(direction):
    d = Vec.of(direction)
    sx = (d[0] > 1e-9) - (d[0] < -1e-9)
    sy = (d[1] > 1e-9) - (d[1] < -1e-9)
    return _ANCHORS[(sx, sy)]


