class Text(VMobject):
    def __init__(self, text, font_size=DEFAULT_FONT_SIZE, font="", weight=NORMAL, slant=NORMAL,
                 line_spacing=-1, t2c=None, letter_spacing=0, **kwargs):
        text = str(text)
        self.text = text
        # font: a family name, or a font file beside the .py ("Brand.ttf"), sent as written.
        geom = {"text": text, "font_size": _num(font_size), "font": font, "weight": weight,
                "slant": slant, "line_spacing": _num(line_spacing), "letter_spacing": _num(letter_spacing)}
        if t2c:
            geom["t2c"] = {str(k): _color(v) for k, v in t2c.items()}
        self._make("text", geom, kwargs, _FILLED, n=sum(1 for ch in text if not ch.isspace()))



def _split_tex(strings, isolate):
    """Manim's part rule: each argument is a part, {{ … }} marks parts too
    ("{{ a }} + {{ b }}" is a, +, b), and every substring to isolate becomes
    its own part. Parts are sent trimmed, so get_part_by_tex("a") finds one."""
    pieces = []
    for s in strings:
        s = str(s)
        if "{{" in s:
            for chunk in s.replace("}}", "{{").split("{{"):
                if chunk.strip():
                    pieces.append(chunk.strip())
        elif s.strip():
            pieces.append(s.strip())
    isolate = sorted({str(x) for x in isolate if x}, key=len, reverse=True)
    if not isolate:
        return pieces
    out = []
    for p in pieces:
        i, start = 0, 0
        while i < len(p):
            hit = next((x for x in isolate if p.startswith(x, i)), None)
            if hit:
                if p[start:i].strip():
                    out.append(p[start:i].strip())
                out.append(hit)
                i += len(hit)
                start = i
            else:
                i += 1
        if p[start:].strip():
            out.append(p[start:].strip())
    return out


class MathTex(VMobject):
    _kind = "mathtex"
    _sep = " "

    def __init__(self, *tex_strings, arg_separator=None, substrings_to_isolate=None, tex_to_color_map=None,
                 font_size=DEFAULT_FONT_SIZE, tex_environment=None, **kwargs):
        cmap = dict(tex_to_color_map or {})
        parts = _split_tex(tex_strings, list(substrings_to_isolate or []) + list(cmap))
        self._parts = parts
        self.tex_string = (self._sep if arg_separator is None else arg_separator).join(parts)
        geom = {"tex_strings": parts, "font_size": _num(font_size),
                "arg_separator": self._sep if arg_separator is None else arg_separator}
        if tex_environment is not None:
            # How lines (\\) are laid out: "flushleft", "center", "align*", …; absent = the default.
            geom["tex_environment"] = str(tex_environment)
        self._make(self._kind, geom, kwargs, _FILLED, n=len(parts))
        for tex, col in cmap.items():
            self.set_color_by_tex(tex, col)

    def get_parts_by_tex(self, tex, substring=True, case_sensitive=True):
        f = (lambda s: s) if case_sensitive else (lambda s: s.lower())
        hits = [i for i, p in enumerate(self._parts)
                if (f(tex) in f(p) if substring else f(tex) == f(p))]
        return VGroup(*[self[i] for i in hits])

    def get_part_by_tex(self, tex, **kwargs):
        for i, p in enumerate(self._parts):
            if tex in p:
                return self[i]
        return None

    def index_of_part_by_tex(self, tex, **kwargs):
        for i, p in enumerate(self._parts):
            if tex in p:
                return i
        return -1

    index_of_part = index_of_part_by_tex

    def set_color_by_tex(self, tex, color, **kwargs):
        for i, p in enumerate(self._parts):
            if tex in p:
                self[i].set_color(color)
        return self

    def set_color_by_tex_to_color_map(self, texs_to_color_map, **kwargs):
        for tex, col in texs_to_color_map.items():
            self.set_color_by_tex(tex, col)
        return self


class Tex(MathTex):
    _kind = "tex"
    _sep = ""


class Title(Tex):
    """A Tex at the top, underlined (the underline is its last part)."""

    def __init__(self, *text_parts, include_underline=True, match_underline_width_to_text=False,
                 underline_buff=MED_SMALL_BUFF, **kwargs):
        Tex.__init__(self, *text_parts, **kwargs)
        self.to_edge(UP)
        if include_underline:
            w, _h = _frame_size()
            self.underline = Line(LEFT, RIGHT).next_to(self, DOWN, buff=underline_buff)
            if match_underline_width_to_text:
                self.underline.match_width(self)
            else:
                self.underline.scale_to_fit_width(w - 2)
            self.add(self.underline)
            self._n += 1


def _number_tex(number, num_decimal_places, include_sign):
    s = ("%+." if include_sign else "%.") + str(int(num_decimal_places)) + "f"
    return s % number


def _real_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _decimal_text(number, num_decimal_places, include_sign, group_with_commas):
    s = ("{:+," if include_sign else "{:,") if group_with_commas else ("{:+" if include_sign else "{:")
    return (s + ".%df}" % int(num_decimal_places)).format(number)


class DecimalNumber(VMobject):
    """A number drawn digit by digit, so changing it is cheap."""

    def __init__(self, number=0, num_decimal_places=2, mob_class=None, include_sign=False,
                 group_with_commas=True, digit_buff_per_font_unit=0.001, show_ellipsis=False, unit=None,
                 unit_buff_per_font_unit=0, include_background_rectangle=False, edge_to_fix=LEFT,
                 font_size=DEFAULT_FONT_SIZE, stroke_width=0, fill_opacity=1.0, **kwargs):
        self.number = number
        self.num_decimal_places = num_decimal_places
        n = None
        if _real_number(number):
            text = _decimal_text(number, num_decimal_places, include_sign, group_with_commas)
            n = len(text) + (1 if unit else 0) + (3 if show_ellipsis else 0)
        self._make("decimal_number", {
            "number": _num(number), "num_decimal_places": int(num_decimal_places),
            "include_sign": bool(include_sign), "group_with_commas": bool(group_with_commas),
            "show_ellipsis": bool(show_ellipsis), "unit": unit, "edge_to_fix": _P(edge_to_fix),
            "include_background_rectangle": bool(include_background_rectangle), "font_size": _num(font_size),
        }, dict(kwargs, stroke_width=stroke_width, fill_opacity=fill_opacity), _FILLED, n=n)

    def set_value(self, number):
        self.number = number
        return self._op("set_value", {"value": _num(number)})

    def get_value(self):
        if _real_number(self.number) and _st().trace is None:
            return self.number
        return Expr(["get", self._ref(), "value"], "s")

    def increment_value(self, delta_t=1):
        if _real_number(self.number) and _real_number(delta_t):
            self.number += delta_t
        return self._op("increment_value", {"value": _num(delta_t)})


class Integer(DecimalNumber):
    def __init__(self, number=0, num_decimal_places=0, **kwargs):
        DecimalNumber.__init__(self, number, num_decimal_places=num_decimal_places, **kwargs)


class ValueTracker(Mobject):
    """A number on the timeline: animate it, and have updaters follow it."""

    def __init__(self, value=0, **kwargs):
        self._value = self._initial = float(value) if _real_number(value) else 0.0
        self._make("value_tracker", {"value": _num(value)}, kwargs, {}, n=0)

    def get_value(self):
        st = _st()
        tr = st.trace
        real = (tr is not None and tr.real) or (tr is None and _live_phase())
        if real and self.__dict__.get("_tmpl") is None:
            if st.anim_v is None:   # no frame from the page yet: the timeline's start
                return self._initial if st.trace is not None else self._value
            return st.anim_v.get(self._id, self._value)
        return Expr(["val", self._ref()], "s")

    def set_value(self, value):
        if _real_number(value):
            self._value = float(value)
        return self._op("set_value", {"value": _num(value)})

    def increment_value(self, d_value):
        if _real_number(d_value):
            self._value += d_value
        return self._op("increment_value", {"value": _num(d_value)})

    def __iadd__(self, d_value):
        return self.increment_value(d_value)

    def __isub__(self, d_value):
        return self.increment_value(-d_value)


class Variable(VGroup):
    """label = value, with a tracker (var.tracker) that the value follows."""

    def __init__(self, var, label, var_type=None, num_decimal_places=2, **kwargs):
        var_type = var_type or DecimalNumber
        label = MathTex(label) if isinstance(label, str) else label
        # As Manim's: the label carries its "=", so the parts are [label, value].
        self.label = VGroup(label, MathTex("=")).arrange(RIGHT)
        self.tracker = ValueTracker(var)
        if var_type is Integer or (isinstance(var_type, type) and issubclass(var_type, Integer)):
            self.value = var_type(var, **kwargs)
        else:
            self.value = var_type(var, num_decimal_places=num_decimal_places, **kwargs)
        VGroup.__init__(self, self.label, self.value)
        self.arrange(RIGHT)
        tracker = self.tracker
        self.value.add_updater(lambda v: v.set_value(tracker.get_value()))


# ---------------------------------------------------------------- updaters
#
# An updater is TRACED: called once with symbolic values (tracker values,
# positions, the time, dt), so its ops become formulas the engine runs every
# frame — scrubbing and recording stay exact and Python stays idle. One that
# cannot be traced (an if on a value, math.sin, a call we cannot follow) runs in
# Python every frame instead: the runtime stays live, and its ops are sent as
# live overrides at the frame's timeline time (anim_t in the tick payload).

_RELATIVE_OPS = ("shift", "rotate", "scale", "stretch", "increment_value", "rotate_about_origin")


class _Trace:
    __slots__ = ("ops", "next_key", "real")

    def __init__(self, real):
        self.ops = []        # [name, args, target] on existing objects
        self.next_key = 0    # templates made inside the traced function
        self.real = real     # Python fallback: trackers and time are real numbers


def _run_trace(fn, args, real=False):
    st = _st()
    prev = st.trace
    tr = st.trace = _Trace(real)
    try:
        return tr, fn(*args), None
    except Exception as e:  # noqa: BLE001 — any failure means: run it in Python instead
        if real:
            raise
        return tr, None, e
    finally:
        st.trace = prev


def _takes_dt(fn):
    try:
        params = [p for p in inspect.signature(fn).parameters.values()
                  if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)]
    except (TypeError, ValueError):
        return False
    return len(params) >= 2 or any(p.name == "dt" for p in params)


def _fn_line(fn):
    code = getattr(fn, "__code__", None)
    if code is not None and code.co_filename == _rt.USER_FILE:
        return code.co_firstlineno
    return _rt._user_line()


def _new_uid():
    st = _st()
    uid = st.next_uid
    st.next_uid += 1
    return uid


def _wire(v):
    """A template ({key, kind, props, ops}) as the engine takes it: [kind, props, ops],
    nested wherever one appears. A reference to another template cannot be sent."""
    if isinstance(v, dict):
        if "kind" in v and "key" in v:
            return [v["kind"], _wire(v["props"]), [[op[0], _wire(op[1])] for op in v["ops"]]]
        if "tmpl" in v:
            raise _Untraceable("one object it makes refers to another one it makes")
        return {k: _wire(x) for k, x in v.items()}
    if isinstance(v, (list, tuple)):
        if any(isinstance(x, Expr) for x in v):
            return _j(v)   # a point with a formula in it: {"$pt": …}
        return [_wire(x) for x in v]
    if isinstance(v, (Expr, Mobject)):
        return _wire(_j(v))
    return v


def _per_frame(args, name, k):
    """A per-frame relative op as a rate: its amount times k = 60·dt (Manim's 60 fps)."""
    def times(v):
        v = _j(v)
        if isinstance(v, dict):
            key = "$pt" if "$pt" in v else "$x"
            return {key: ["*", v[key], k]}
        if isinstance(v, list):
            return {"$pt": ["*", v, k]}
        return {"$x": ["*", v, k]}

    def power(v):
        v = _j(v)
        return {"$x": ["**", v.get("$x") if isinstance(v, dict) else v, k]}

    a = dict(args)
    if name == "shift":
        a["vectors"] = [times(v) for v in a.get("vectors", [])]
    elif name in ("rotate", "rotate_about_origin"):
        a["angle"] = times(a["angle"])
    elif name == "increment_value":
        a["value"] = times(a["value"])
    elif name == "scale":
        a["scale_factor"] = power(a["scale_factor"])
    elif name == "stretch":
        a["factor"] = power(a["factor"])
    return a


def _by_target(ops):
    out = {}
    for name, args, target in ops:
        out.setdefault(repr(target), (target, []))[1].append([name, args])
    return list(out.values())


def _add_updater(mob, fn):
    if mob.__dict__.get("_tmpl") is not None or _st().trace is not None:
        raise _Untraceable("it adds an updater")
    dt = _takes_dt(fn)
    tr, result, err = _run_trace(fn, (mob, _var("dt")) if dt else (mob,))
    entries = []
    if err is None:
        ops = tr.ops
        kind = "dt" if dt else "op"
        if not dt and any(op[0] in _RELATIVE_OPS for op in ops):
            k = ["*", ["dt"], float(config.frame_rate or 60)]
            ops = [[name, _per_frame(args, name, k) if name in _RELATIVE_OPS else args, target]
                   for name, args, target in ops]
            kind = "dt"
        try:
            groups = [(target, _wire(o)) for target, o in _by_target(ops)] or [(mob._t(), [])]
        except _Untraceable as e:
            err = e
        else:
            for target, o in groups:
                uid = _new_uid()
                _call("add_updater", target, {"uid": uid, "kind": kind, "ops": o})
                entries.append((target, uid))
    if err is not None:
        u = _PyUpdater("dt" if dt else "op", fn, mob)
        _fallback(u)
        entries.append((None, u))
    mob.__dict__.setdefault("updaters", []).append((fn, entries))


def _fallback(u):
    _tell("fb%d" % id(u), "Note: the updater on line %d runs in Python on every frame, so the program "
                          "keeps running." % _fn_line(u.fn))
    _st().fallbacks.append(u)


def _live_op(name, args, target, accumulate=False):
    """One change on top of the timeline, at whatever time is drawn."""
    if (name == "set_value" and not accumulate and isinstance(target, int)
            and isinstance(_st().objects.get(target), ValueTracker)):
        _call("live_set", target, _wire(args.get("value")))
        return
    if accumulate:
        _call("live_op", target, name, _wire(args), {"accumulate": True})
    else:
        _call("live_op", target, name, _wire(args))


class _PyUpdater:
    """An updater run in Python each frame; its ops become live overrides."""

    def __init__(self, kind, fn, mob):
        self.kind, self.fn, self.mob = kind, fn, mob
        self.last_t = None
        self.active = True

    def run(self, st):
        if not self.active:
            return
        if self.kind == "dt":
            t = st.anim_t
            last, self.last_t = self.last_t, t
            if last is None or t <= last:
                return
            tr, _r, _e = _run_trace(self.fn, (self.mob, t - last), real=True)
            for name, args, target in tr.ops:
                _live_op(name, args, target, accumulate=True)
            return
        if self.kind == "redraw":
            tr, result, _e = _run_trace(self.fn, (), real=True)
            if isinstance(result, Mobject):
                _live_op("become", {"mobject": result._embed()}, self.mob._t())
        else:
            tr, _r, _e = _run_trace(self.fn, (self.mob,), real=True)
        for name, args, target in tr.ops:
            _live_op(name, args, target)


def always_redraw(func):
    """A mobject rebuilt from func() every frame."""
    st = _st()
    tr, result, err = _run_trace(func, ())
    if err is None and isinstance(result, Mobject) and result.__dict__.get("_tmpl") is not None:
        try:
            make = _wire(result._tmpl)
        except _Untraceable as e:
            err = e
        else:
            result._tmpl = None
            result._id = st.next_id
            st.next_id += 1
            st.objects[result._id] = result
            uid = _new_uid()
            _call("add_updater", result._id, {"uid": uid, "kind": "redraw", "make": make})
            result.__dict__["updaters"] = [(func, [(result._id, uid)])]
            return result
    if err is None and not isinstance(result, Mobject):
        raise TypeError("always_redraw needs a function that returns a mobject, such as "
                        "lambda: Line(a.get_center(), b.get_center())")
    holder = VGroup()
    u = _PyUpdater("redraw", func, holder)
    _fallback(u)
    holder.__dict__["updaters"] = [(func, [(None, u)])]
    return holder


def always(method, *args, **kwargs):
    """always(m.next_to, other, UP): keep calling the method every frame."""
    mob = method.__self__
    mob.add_updater(lambda m: method(*args, **kwargs))
    return mob


def f_always(method, *arg_generators, **kwargs):
    """f_always(m.set_x, lambda: t.get_value()): the arguments are worked out every frame."""
    mob = method.__self__
    mob.add_updater(lambda m: method(*[g() for g in arg_generators], **kwargs))
    return mob


def always_shift(mobject, direction=RIGHT, rate=0.1):
    return mobject.add_updater(lambda m, dt: m.shift(dt * rate * direction))


def always_rotate(mobject, rate=20 * DEGREES, **kwargs):
    return mobject.add_updater(lambda m, dt: m.rotate(dt * rate, **kwargs))


class TracedPath(VMobject):
    """The path a point leaves behind: TracedPath(dot.get_center)."""

    def __init__(self, traced_point_func, stroke_width=2, stroke_color=WHITE, dissipating_time=None, **kwargs):
        tr, point, err = _run_trace(traced_point_func, ())
        if err is not None or not _is_sym(point):
            raise TypeError("TracedPath needs a point it can follow, such as TracedPath(dot.get_center)")
        self._make("traced_path", {"point": _P(point), "dissipating_time": dissipating_time},
                   dict(kwargs, stroke_width=stroke_width, stroke_color=stroke_color), n=0)


# ---------------------------------------------------------------- Pyctures inside a scene

class PycturesCanvas(Mobject):
    """A picture drawn with Pyctures' ctx every frame, placed in the scene:
    draw(ctx, t) draws in pixels (resolution per scene unit); t is the time."""

    def __init__(self, width=4.0, height=3.0, draw=None, resolution=100, **kwargs):
        w, h = float(width), float(height)
        ratio = ((_rt.S.ns or {}).get("pixel_ratio", 1) or 1)
        self._lw, self._lh = max(1, int(round(w * resolution))), max(1, int(round(h * resolution)))
        pw, ph = max(1, int(round(self._lw * ratio))), max(1, int(round(self._lh * ratio)))
        self._ratio = ratio
        self._draw_fn = draw
        self._make("pyctures_canvas", {"width": w, "height": h, "px_width": pw, "px_height": ph}, kwargs, {}, n=0)
        # The engine makes the canvas element; Python draws on it through a handle.
        self._canvas = _rt.JsRef(H_ANIM).canvas_for(self._id)
        self._ctx = self._canvas.getContext("2d")
        _st().canvases.append(self)

    @property
    def ctx(self):
        return self._ctx

    def _redraw(self):
        if self._draw_fn is None:
            return
        g = self._ctx
        g.setTransform(self._ratio, 0, 0, self._ratio, 0, 0)
        g.clearRect(0, 0, self._lw, self._lh)
        self._draw_fn(g, _st().anim_t)


def _style_dict(d):
    """A config dict (axis_config={"color": GREEN}): colours as '#RRGGBB', the rest as JSON."""
    return {str(k): _color(v) if str(k).endswith("color") else _j(v) for k, v in dict(d or {}).items()}


def _range3(r, default):
    r = list(default if r is None else r)
    if len(r) == 2:
        r.append(1.0)
    return [_num(x) for x in r]


class _Curve(VMobject):
    """A curve sampled in Python once (axes.plot, ParametricFunction, get_area)."""

    def __init__(self, points, axes=None, function=None, closed=False, x_range=None, **kwargs):
        self._func = function
        self._axes = axes
        self._x_range = x_range
        # Pen-up gaps (None) split the curve into segments.
        segs, seg = [], []
        for p in points:
            if p is None:
                if seg:
                    segs.append(seg)
                seg = []
            else:
                seg.append(p)
        if seg:
            segs.append(seg)
        if axes is not None:
            # In the axes' own coordinates; the engine places them on the axes.
            geom = {"segments": segs, "axes": axes._ref()}
            if closed:
                geom.update(closed=True, use_smoothing=False)
            self._make("graph", geom, kwargs, n=0)
        else:
            self._make("vmobject", {"subpaths": segs, "smooth": not closed, "closed": bool(closed)}, kwargs, n=0)

    def underlying_function(self, x):
        return self._func(x)


def _sample(fn, t0, t1, step, to_point):
    span = t1 - t0
    if span <= 0:
        return []
    step = min(abs(step) if step else span, span / 200.0)
    count = min(4000, int(math.ceil(span / step)))
    pts, pen = [], False
    for i in range(count + 1):
        t = t0 + span * i / count
        try:
            p = to_point(fn, t)
            # A symbolic value (a tracker inside the function) is worked out by the
            # engine, every frame when the curve is redrawn.
            ok = all(isinstance(v, Expr) or (v == v and abs(v) < 1e7) for v in p)
        except (ArithmeticError, ValueError):
            ok = False
        if ok:
            pts.append(p)
            pen = True
        elif pen:
            pts.append(None)
            pen = False
    while pts and pts[-1] is None:
        pts.pop()
    return pts


def _xy(fn, x):
    y = fn(x)
    if isinstance(y, Expr):
        if y.shape != "s":
            raise TypeError("a plotted function must return a number")
        return [float(x), y, 0.0]
    return [float(x), float(y), 0.0]


def _xyz(fn, t):
    p = _unarray(fn(t))
    if _is_sym(p):
        p = list(p)
        return (p + [0.0, 0.0])[:3] if len(p) < 3 else p[:3]
    return list(Vec.of(p))


class ParametricFunction(_Curve):
    def __init__(self, function, t_range=(0, 1), color=YELLOW, **kwargs):
        t = _range3(t_range, (0, 1, 0.01))
        _Curve.__init__(self, _sample(function, t[0], t[1], t[2] if len(t_range) > 2 else None, _xyz),
                       function=function, color=color, **kwargs)


class FunctionGraph(ParametricFunction):
    def __init__(self, function, x_range=None, color=YELLOW, **kwargs):
        w, _h = _frame_size()
        r = _range3(x_range, (-w / 2, w / 2, 0.01))
        _Curve.__init__(self, _sample(function, r[0], r[1], r[2], _xy), function=function, color=color,
                        x_range=(r[0], r[1]), **kwargs)


class NumberLine(VMobject):
    def __init__(self, x_range=None, length=None, unit_size=1, include_numbers=False, include_tip=False,
                 **kwargs):
        w, _h = _frame_size()
        half = float(round(w / 2))
        r = _range3(x_range, (-half, half, 1))
        self.x_range = r
        self._make("number_line", {"x_range": r, "length": _num(length) if length else None,
                                  "unit_size": _num(unit_size), "include_numbers": bool(include_numbers),
                                  "include_tip": bool(include_tip)}, kwargs, n=None)

    def number_to_point(self, number):
        return Point(["c2p", self._ref(), _coord(number), 0.0])

    n2p = number_to_point


class Axes(VMobject):
    _kind = "axes"

    def __init__(self, x_range=None, y_range=None, x_length=None, y_length=None, axis_config=None,
                 x_axis_config=None, y_axis_config=None, tips=True, **kwargs):
        w, h = _frame_size()
        self.x_range = _range3(x_range, self._default_range(w))
        self.y_range = _range3(y_range, self._default_range(h))
        geom = {"x_range": self.x_range, "y_range": self.y_range,
                "x_length": _num(x_length) if x_length is not None else self._length(round(w) - 2, self.x_range),
                "y_length": _num(y_length) if y_length is not None else self._length(round(h) - 2, self.y_range),
                "tips": bool(tips), "axis_config": _style_dict(axis_config),
                "x_axis_config": _style_dict(x_axis_config), "y_axis_config": _style_dict(y_axis_config)}
        geom.update(self._extra(kwargs))
        self._make(self._kind, geom, kwargs, n=4 if isinstance(self, NumberPlane) else 2)

    def _length(self, frame_length, r):
        return float(frame_length)

    def _default_range(self, frame_length):
        # Whole units: x -7..7 and y -4..4 in the 16:9 frame.
        half = float(round(frame_length / 2))
        return (-half, half, 1)

    def _extra(self, kwargs):
        return {}

    _axis_index = (0, 1)   # where the x and y axes sit among the parts

    @property
    def x_axis(self):
        return self[self._axis_index[0]]

    @property
    def y_axis(self):
        return self[self._axis_index[1]]

    def get_axes(self):
        return VGroup(self.x_axis, self.y_axis)

    def coords_to_point(self, *coords):
        if len(coords) == 1:
            coords = tuple(_unarray(coords[0]))
        x = _coord(coords[0])
        y = _coord(coords[1]) if len(coords) > 1 else 0.0
        return Point(["c2p", self._ref(), x, y])

    c2p = coords_to_point

    def plot(self, function, x_range=None, color=None, **kwargs):
        r = list(x_range) if x_range is not None else list(self.x_range)
        r = _range3(r, self.x_range)
        step = r[2] if (x_range is not None and len(x_range) > 2) else None
        kw = dict(kwargs)
        kw["color"] = color if color is not None else kw.get("color", YELLOW)
        g = _Curve(_sample(function, r[0], r[1], step, _xy), axes=self, function=function,
                   x_range=(r[0], r[1]), **kw)
        g.color = kw["color"]
        return g

    get_graph = plot

    def plot_parametric_curve(self, function, t_range=(0, 1), color=YELLOW, **kwargs):
        t = _range3(t_range, (0, 1, 0.01))
        return _Curve(_sample(function, t[0], t[1], t[2] if len(t_range) > 2 else None, _xyz),
                      axes=self, function=function, color=color, **kwargs)

    def input_to_graph_point(self, x, graph):
        fn = getattr(graph, "_func", None)
        if fn is None:
            raise TypeError("input_to_graph_point needs a graph made with axes.plot(...)")
        return self.c2p(x, fn(x))

    i2gp = input_to_graph_point

    def get_graph_label(self, graph, label="f(x)", x_val=None, direction=RIGHT, buff=MED_SMALL_BUFF,
                        color=None, dot=False, dot_config=None):
        m = label if isinstance(label, Mobject) else MathTex(label)
        if x_val is None:
            x_val = self.x_range[1]
        m.next_to(self.i2gp(x_val, graph), direction, buff=buff)
        m.set_color(color if color is not None else getattr(graph, "color", YELLOW))
        return m

    def get_x_axis_label(self, label, edge=UR, direction=UR, buff=SMALL_BUFF, **kwargs):
        m = label if isinstance(label, Mobject) else MathTex(label)
        return m.next_to(self.x_axis.get_corner(edge), direction, buff=buff)

    def get_y_axis_label(self, label, edge=UR, direction=UR, buff=SMALL_BUFF, **kwargs):
        m = label if isinstance(label, Mobject) else MathTex(label)
        return m.next_to(self.y_axis.get_corner(edge), direction, buff=buff)

    def get_axis_labels(self, x_label="x", y_label="y"):
        return VGroup(self.get_x_axis_label(x_label), self.get_y_axis_label(y_label))

    def add_coordinates(self, *axes_numbers, num_decimal_places=None, **kwargs):
        return self._op("add_coordinates", {"num_decimal_places": num_decimal_places})

    # -- helpers built here from the plotted function (Python knows it)

    def _graph_fn(self, graph, what):
        fn = getattr(graph, "_func", None)
        if fn is None:
            raise TypeError("%s needs a graph made with axes.plot(...)" % what)
        return fn

    def get_area(self, graph, x_range=None, color=(BLUE, GREEN), opacity=0.3, bounded_graph=None, **kwargs):
        f = self._graph_fn(graph, "get_area")
        a, b = x_range if x_range is not None else (graph._x_range or self.x_range[:2])
        g = getattr(bounded_graph, "_func", None) or (lambda x: 0.0)
        top = [p for p in _sample(f, a, b, None, _xy) if p is not None]
        bottom = [p for p in _sample(g, a, b, None, _xy) if p is not None]
        area = _Curve(top + bottom[::-1], axes=self, closed=True, fill_opacity=opacity, stroke_width=0,
                      color=list(color) if isinstance(color, (list, tuple)) else color, **kwargs)
        return area

    def get_riemann_rectangles(self, graph, x_range=None, dx=0.1, input_sample_type="left", stroke_width=1,
                               stroke_color=BLACK, fill_opacity=1, color=(BLUE, GREEN), show_signed_area=True,
                               bounded_graph=None, blend=False, width_scale_factor=1.001):
        f = self._graph_fn(graph, "get_riemann_rectangles")
        g = getattr(bounded_graph, "_func", None) or (lambda x: 0.0)
        a, b = x_range if x_range is not None else self.x_range[:2]
        n = max(1, int(round((b - a) / dx)))
        colors = color_gradient(color if isinstance(color, (list, tuple)) else [color], n)
        rects = []
        for i in range(n):
            x0 = a + i * dx
            x1 = x0 + dx * width_scale_factor
            xs = {"left": x0, "right": x0 + dx, "center": x0 + dx / 2}.get(input_sample_type, x0)
            y = f(xs)
            base = g(xs)
            pts = [[x0, base, 0.0], [x1, base, 0.0], [x1, y, 0.0], [x0, y, 0.0]]
            rects.append(_Curve(pts, axes=self, closed=True, fill_opacity=fill_opacity, stroke_width=stroke_width,
                                stroke_color=stroke_color, fill_color=colors[i], color=colors[i]))
        return VGroup(*rects)

    def get_vertical_line(self, point, line_config=None, line_func=None, **kwargs):
        line_func = line_func or DashedLine
        foot = Point(["v", [["idx", _tree(point), 0], ["idx", ["c2p", self._ref(), 0.0, 0.0], 1], 0.0]])
        return line_func(point, foot, **dict(line_config or {}, **kwargs))

    def get_horizontal_line(self, point, line_config=None, line_func=None, **kwargs):
        line_func = line_func or DashedLine
        foot = Point(["v", [["idx", ["c2p", self._ref(), 0.0, 0.0], 0], ["idx", _tree(point), 1], 0.0]])
        return line_func(point, foot, **dict(line_config or {}, **kwargs))

    def get_T_label(self, x_val, graph, label=None, label_color=None, triangle_size=MED_SMALL_BUFF,
                    triangle_color=WHITE, line_func=None, line_color=YELLOW):
        line_func = line_func or Line
        tri = Triangle(color=triangle_color, fill_opacity=1).scale_to_fit_height(triangle_size)
        tri.move_to(self.c2p(x_val, 0), UP)
        parts = [tri]
        if label is not None:
            lab = label if isinstance(label, Mobject) else MathTex(label)
            lab.next_to(tri, DOWN)
            if label_color is not None:
                lab.set_color(label_color)
            parts.append(lab)
        parts.append(line_func(self.c2p(x_val, 0), self.i2gp(x_val, graph), color=line_color))
        return VGroup(*parts)

    def get_secant_slope_group(self, x, graph, dx=None, dx_line_color=YELLOW, dy_line_color=None,
                               dx_label=None, dy_label=None, include_secant_line=True, secant_line_color=GREEN,
                               secant_line_length=10):
        f = self._graph_fn(graph, "get_secant_slope_group")
        dx = dx if dx is not None else (self.x_range[1] - self.x_range[0]) / 10
        p1, p2 = self.c2p(x, f(x)), self.c2p(x + dx, f(x + dx))
        corner = self.c2p(x + dx, f(x))
        dx_line = Line(p1, corner, color=dx_line_color)
        dy_line = Line(corner, p2, color=dy_line_color or getattr(graph, "color", YELLOW))
        parts = [dx_line, dy_line]
        if dx_label is not None:
            parts.append((dx_label if isinstance(dx_label, Mobject) else MathTex(dx_label)).next_to(dx_line, DOWN))
        if dy_label is not None:
            parts.append((dy_label if isinstance(dy_label, Mobject) else MathTex(dy_label)).next_to(dy_line, RIGHT))
        if include_secant_line:
            secant = Line(p1, p2, color=secant_line_color)
            secant.scale(secant_line_length / secant.get_length())
            parts.append(secant)
        return VGroup(*parts)


