# ---------------------------------------------------------------- .animate

class _Animate:
    """m.animate.shift(UP).scale(2): records the ops, played as one animation."""

    def __init__(self, mob):
        self._mob = mob
        self._ops = []
        self._kw = {}

    def __call__(self, **kwargs):
        self._kw.update(kwargs)
        return self

    def __getattr__(self, name):
        if name.startswith("_"):
            raise AttributeError(name)
        fn = getattr(self._mob, name)
        if not callable(fn):
            raise AttributeError("%s.animate.%s is not something that can be animated" % (
                type(self._mob).__name__, name))

        def record(*args, **kwargs):
            st = _st()
            prev = st.capture
            st.capture = (self._mob._t(), self._ops)
            try:
                fn(*args, **kwargs)
            finally:
                st.capture = prev
            return self
        return record

    def _anim(self):
        a = {"kind": "animate", "target": self._mob._t(), "args": {"ops": self._ops}}
        _timing(a, self._kw)
        return a

    def _added(self):
        return [self._mob]

    def _removed(self):
        return []


# ---------------------------------------------------------------- animations

def _timing(d, kw):
    for k in ("run_time", "lag_ratio"):
        if kw.get(k) is not None:
            d[k] = _num(kw[k])
    if kw.get("rate_func") is not None:
        d["rate_func"] = _rate(kw["rate_func"])
    return d


class Animation:
    kind = "animation"

    def __init__(self, mobject=None, *args, run_time=None, rate_func=None, lag_ratio=None, **kwargs):
        # Positional arguments after the mobject are the animation's own
        # (Circumscribe(m, Circle), Indicate(m, 1.5)), as in Manim.
        self.mobject = mobject
        self._kw = {"run_time": run_time, "rate_func": rate_func, "lag_ratio": lag_ratio}
        self._args = self._make_args(*args, **kwargs)

    def _make_args(self, **kwargs):
        return {}

    def _anim(self):
        t = self.mobject._t() if isinstance(self.mobject, Mobject) else None
        return _timing({"kind": self.kind, "target": t, "args": self._args}, self._kw)

    def _added(self):
        return [self.mobject] if isinstance(self.mobject, Mobject) else []

    def _removed(self):
        return []

    @property
    def run_time(self):
        return self._kw.get("run_time") or 1.0

    def set_run_time(self, run_time):
        self._kw["run_time"] = run_time
        return self

    def set_rate_func(self, rate_func):
        self._kw["rate_func"] = rate_func
        return self


