class _Fade(Animation):
    def __init__(self, *mobjects, shift=None, target_position=None, scale=1, **kwargs):
        mobs = _flat(mobjects)
        self._many = mobs if len(mobs) > 1 else None
        self._fade_kw = {"shift": shift, "target_position": target_position, "scale": scale}
        Animation.__init__(self, mobs[0] if mobs else None, **kwargs)

    def _make_args(self, **kwargs):
        args = {}
        kw = self._fade_kw
        if kw["shift"] is not None:
            args["shift"] = _P(kw["shift"])
        if kw["target_position"] is not None:
            args["target_position"] = _P(kw["target_position"])
        if kw["scale"] != 1:
            args["scale"] = _num(kw["scale"])
        return args

    def _anim(self):
        if self._many is None:
            return Animation._anim(self)
        items = [{"kind": self.kind, "target": m._t(), "args": self._args} for m in self._many]
        return _timing({"kind": "group", "items": items}, self._kw)

    def _added(self):
        return self._many or Animation._added(self)


