def _as_anim(a, where="play()"):
    if isinstance(a, (Animation, _Animate)):
        return a
    if isinstance(a, Mobject):
        raise TypeError("%s takes animations, such as Create(m) or m.animate.shift(UP); got a %s"
                        % (where, type(a).__name__))
    raise TypeError("%s takes animations, such as Create(m) or m.animate.shift(UP); got %r" % (where, a))


class AnimationGroup(Animation):
    kind = "group"

    def __init__(self, *animations, group=None, run_time=None, rate_func=None, lag_ratio=None, **kwargs):
        items = []
        for a in animations:
            if isinstance(a, (list, tuple, types.GeneratorType)):
                items.extend(_as_anim(x, type(self).__name__ + "()") for x in a)
            else:
                items.append(_as_anim(a, type(self).__name__ + "()"))
        self.animations = items
        Animation.__init__(self, None, run_time=run_time, rate_func=rate_func,
                           lag_ratio=self._lag(lag_ratio))

    def _lag(self, lag_ratio):
        return lag_ratio

    def _anim(self):
        return _timing({"kind": self.kind, "items": [a._anim() for a in self.animations]}, self._kw)

    def _added(self):
        return [m for a in self.animations for m in a._added()]

    def _removed(self):
        return [m for a in self.animations for m in a._removed()]


