def LaggedStartMap(AnimationClass, mobject, arg_creator=None, run_time=2, **kwargs):
    anims = [AnimationClass(*(arg_creator(m) if arg_creator else (m,))) for m in mobject]
    return LaggedStart(*anims, run_time=run_time, **kwargs)


