def _text_kwargs(kwargs):
    return {k: kwargs.pop(k) for k in ("font_size", "font", "weight", "slant", "line_spacing", "letter_spacing")
            if k in kwargs}


class Paragraph(VGroup):
    def __init__(self, *text, line_spacing=-1, alignment=None, **kwargs):
        lines = "\n".join(str(t) for t in text).split("\n")
        self.lines_text = lines
        self._kids = None
        geom = {"lines": lines, "line_spacing": _num(line_spacing), "alignment": alignment,
                "font_size": DEFAULT_FONT_SIZE}
        geom.update(_text_kwargs(kwargs))
        self._make("paragraph", geom, kwargs, _FILLED, n=len(lines))


class BulletedList(VGroup):
    def __init__(self, *items, buff=MED_LARGE_BUFF, dot_scale_factor=2, tex_environment=None, dot_buff=SMALL_BUFF,
                 **kwargs):
        self.items = [str(i) for i in items]
        self._kids = None
        geom = {"items": self.items, "buff": _num(buff), "dot_scale_factor": _num(dot_scale_factor),
                "dot_buff": _num(dot_buff), "font_size": DEFAULT_FONT_SIZE}
        geom.update(_text_kwargs(kwargs))
        self._make("bulleted_list", geom, kwargs, _FILLED, n=len(self.items))

    def fade_all_but(self, index, opacity=0.5):
        for i in range(len(self.items)):
            self[i].set_opacity(1.0 if i == index else opacity)
        return self


class MarkupText(Text):
    def __init__(self, text, fill_opacity=1, stroke_width=0, color=None, font_size=DEFAULT_FONT_SIZE,
                 line_spacing=-1, font="", slant=NORMAL, weight=NORMAL, justify=False, **kwargs):
        import re
        plain = re.sub(r"&[a-z]+;", "x", re.sub(r"<[^>]*>", "", str(text)))
        self.text = str(text)
        self._make("markup_text", {"text": str(text), "font_size": _num(font_size), "line_spacing": _num(line_spacing),
                                   "font": font, "slant": slant, "weight": weight, "justify": bool(justify)},
                   dict(kwargs, color=color or WHITE, fill_opacity=fill_opacity, stroke_width=stroke_width),
                   _FILLED, n=sum(1 for ch in plain if not ch.isspace()))


def _entry(v, element):
    """A table or matrix entry: a string the engine sets in the element kind, or an existing mobject."""
    if isinstance(v, Mobject):
        return v._embed()
    return str(v)


def _element_of(element_to_mobject, default):
    names = {MathTex: "mathtex", Tex: "tex", Text: "paragraph", Paragraph: "paragraph",
             DecimalNumber: "mathtex", Integer: "mathtex"}
    return names.get(element_to_mobject, default)


def _format_entries(rows, element_to_mobject, config):
    if element_to_mobject in (Integer,):
        return [["%d" % int(round(float(x))) for x in r] for r in rows]
    if element_to_mobject in (DecimalNumber,):
        places = int((config or {}).get("num_decimal_places", 2))
        return [[("%." + str(places) + "f") % float(x) for x in r] for r in rows]
    return rows


class Table(VGroup):
    _element = "paragraph"

    def __init__(self, table, row_labels=None, col_labels=None, top_left_entry=None, v_buff=0.8, h_buff=1.3,
                 include_outer_lines=False, include_inner_lines=True, add_background_rectangles_to_entries=False,
                 entries_background_color=BLACK, include_background_rectangle=False,
                 background_rectangle_color=BLACK, element_to_mobject=None, element_to_mobject_config=None,
                 arrange_in_grid_config=None, line_config=None, **kwargs):
        rows = [list(r) for r in table]
        rows = _format_entries(rows, element_to_mobject, element_to_mobject_config)
        element = _element_of(element_to_mobject, self._element)
        self.n_rows = len(rows) + (1 if col_labels else 0)
        self.n_cols = (len(rows[0]) if rows else 0) + (1 if row_labels else 0)
        self._kids = None
        self._make("table", {
            "table": [[_entry(v, element) for v in r] for r in rows], "element": element,
            "row_labels": [m._embed() for m in row_labels] if row_labels else None,
            "col_labels": [m._embed() for m in col_labels] if col_labels else None,
            "top_left_entry": top_left_entry._embed() if top_left_entry is not None else None,
            "v_buff": _num(v_buff), "h_buff": _num(h_buff), "include_outer_lines": bool(include_outer_lines),
            "include_inner_lines": bool(include_inner_lines),
            "include_background_rectangle": bool(include_background_rectangle),
            "background_rectangle_color": _color(background_rectangle_color),
            "add_background_rectangles_to_entries": bool(add_background_rectangles_to_entries),
            "entries_background_color": _color(entries_background_color),
            "line_config": _style_dict(line_config),
        }, kwargs, {}, n=3)

    def get_entries(self, pos=None):
        if pos is None:
            return self[0]
        r, c = pos
        return self[0][(r - 1) * self.n_cols + (c - 1)]

    def get_entries_without_labels(self, pos=None):
        return self.get_entries(pos)

    def get_rows(self):
        return VGroup(*[VGroup(*[self[0][r * self.n_cols + c] for c in range(self.n_cols)])
                        for r in range(self.n_rows)])

    def get_columns(self):
        return VGroup(*[VGroup(*[self[0][r * self.n_cols + c] for r in range(self.n_rows)])
                        for c in range(self.n_cols)])

    def get_horizontal_lines(self):
        return self[1]

    def get_vertical_lines(self):
        return self[2]

    def get_cell(self, pos, **kwargs):
        return SurroundingRectangle(self.get_entries(pos), buff=0.1, **kwargs)


class MathTable(Table):
    _element = "mathtex"


class IntegerTable(Table):
    def __init__(self, table, element_to_mobject=Integer, **kwargs):
        Table.__init__(self, table, element_to_mobject=element_to_mobject, **kwargs)


class DecimalTable(Table):
    def __init__(self, table, element_to_mobject=DecimalNumber, element_to_mobject_config=None, **kwargs):
        Table.__init__(self, table, element_to_mobject=element_to_mobject,
                       element_to_mobject_config=element_to_mobject_config or {"num_decimal_places": 1}, **kwargs)


class Matrix(VMobject):
    _default_element = MathTex
    _default_config = None

    def __init__(self, matrix, v_buff=0.8, h_buff=1.3, bracket_h_buff=MED_SMALL_BUFF,
                 bracket_v_buff=MED_SMALL_BUFF, add_background_rectangles_to_entries=False,
                 include_background_rectangle=False, element_to_mobject=None, element_to_mobject_config=None,
                 element_alignment_corner=DR, left_bracket="[", right_bracket="]", stretch_brackets=True,
                 bracket_config=None, **kwargs):
        rows = [list(r) if isinstance(r, (list, tuple)) or hasattr(r, "tolist") else [r]
                for r in _unarray(matrix)]
        rows = [list(_unarray(r)) for r in rows]
        element_to_mobject = element_to_mobject or self._default_element
        rows = _format_entries(rows, element_to_mobject, element_to_mobject_config or self._default_config)
        self.n_rows = len(rows)
        self.n_cols = len(rows[0]) if rows else 0
        self._make("matrix", {
            "matrix": [[_entry(v, "mathtex") for v in r] for r in rows], "v_buff": _num(v_buff),
            "h_buff": _num(h_buff), "bracket_h_buff": _num(bracket_h_buff), "bracket_v_buff": _num(bracket_v_buff),
            "left_bracket": left_bracket, "right_bracket": right_bracket,
            "element_alignment_corner": _P(element_alignment_corner),
            "include_background_rectangle": bool(include_background_rectangle),
            "add_background_rectangles_to_entries": bool(add_background_rectangles_to_entries),
        }, kwargs, _FILLED, n=3)

    def get_entries(self):
        return self[0]

    def get_mob_matrix(self):
        return [[self[0][r * self.n_cols + c] for c in range(self.n_cols)] for r in range(self.n_rows)]

    def get_rows(self):
        return VGroup(*[VGroup(*row) for row in self.get_mob_matrix()])

    def get_columns(self):
        return VGroup(*[VGroup(*[self[0][r * self.n_cols + c] for r in range(self.n_rows)])
                        for c in range(self.n_cols)])

    def get_brackets(self):
        return VGroup(self[1], self[2])

    def set_column_colors(self, *colors):
        for col, color in zip(self.get_columns(), colors):
            col.set_color(color)
        return self

    def set_row_colors(self, *colors):
        for row, color in zip(self.get_rows(), colors):
            row.set_color(color)
        return self


class IntegerMatrix(Matrix):
    _default_element = Integer


class DecimalMatrix(Matrix):
    _default_element = DecimalNumber
    _default_config = {"num_decimal_places": 1}


class MobjectMatrix(Matrix):
    pass


_CODE_LANGS = {".py": "python", ".js": "javascript", ".ts": "typescript", ".c": "c", ".cpp": "cpp",
               ".java": "java", ".rs": "rust", ".go": "go", ".rb": "ruby", ".sh": "bash", ".html": "html",
               ".css": "css", ".json": "json", ".lua": "lua", ".swift": "swift", ".kt": "kotlin"}


class Code(VMobject):
    def __init__(self, code_file=None, code_string=None, language=None, formatter_style="vim", tab_width=4,
                 add_line_numbers=True, line_numbers_from=1, background="rectangle", background_config=None,
                 paragraph_config=None, **kwargs):
        if code_string is None and code_file is not None:
            with open(code_file) as fh:
                code_string = fh.read()
        code = (code_string or "").expandtabs(tab_width).rstrip("\n")
        if language is None and code_file:
            language = _CODE_LANGS.get("." + str(code_file).rsplit(".", 1)[-1].lower())
        self.code_lines = code.split("\n")
        self._make("code", {"code": code, "language": language or "python", "tab_width": int(tab_width),
                            "add_line_numbers": bool(add_line_numbers), "line_numbers_from": int(line_numbers_from),
                            "background": background, "formatter_style": formatter_style,
                            "background_config": _style_dict(background_config),
                            "paragraph_config": _style_dict(paragraph_config)}, kwargs, {},
                   n=3 if add_line_numbers else 2)

    @property
    def code(self):
        return self[self._n - 1]

    @property
    def line_numbers(self):
        return self[1] if self._n == 3 else None

    @property
    def background(self):
        return self[0]


