class SVGMobject(VMobject):
    def __init__(self, file_name=None, should_center=True, height=2, width=None, color=None, opacity=None,
                 fill_color=None, fill_opacity=None, stroke_color=None, stroke_opacity=None, stroke_width=None,
                 svg_default=None, path_string_config=None, use_svg_cache=True, trace=None, ops=None,
                 remove_background=False, resize=None, **kwargs):
        geom = {"should_center": bool(should_center), "height": None if height is None else _num(height),
                "width": None if width is None else _num(width)}
        extra = ()
        image = _own_attr(file_name, "_cir_image_src") or file_name
        if trace is not None or (isinstance(image, str) and image.lower().endswith(_IMAGE_EXTS)):
            # A picture traced to outlines in the preview (2Vec), after any image ops.
            ref = _preview_object(image)
            if ref is not None:
                self._source = ref
                extra = ({"$h": ref._handle()},)
                image = None
            geom.update(image_src=image, ops=_image_op_chain(ops, remove_background, resize),
                        trace=_trace_params(trace))
            style = {k: v for k, v in dict(color=color, opacity=opacity, fill_color=fill_color,
                                           fill_opacity=fill_opacity, stroke_color=stroke_color,
                                           stroke_opacity=stroke_opacity, stroke_width=stroke_width).items()
                     if v is not None}
            self._make("svg_mobject", geom, dict(kwargs, **style), {}, n=None, extra=extra)
            return
        ref = _preview_object(file_name)
        traced = _own_attr(file_name, "_cir_svg")   # an image's .trace() (pyctures_images.Vector)
        text = file_name if isinstance(file_name, str) else _own_attr(file_name, "svg")
        if isinstance(traced, str):
            geom["svg"] = traced
        elif ref is not None:
            # An SVG worked out in the preview (an image's .trace()): sent as the
            # call's 4th argument, which the page resolves to the object.
            self._source = ref
            extra = ({"$h": ref._handle()},)
        elif isinstance(text, str) and text.lstrip().startswith("<"):
            geom["svg"] = text   # SVG markup itself
        else:
            try:
                with open(str(file_name), encoding="utf-8") as fh:
                    geom["svg"] = fh.read()
            except (OSError, TypeError):
                geom["file_name"] = str(file_name)
        style = {k: v for k, v in dict(color=color, opacity=opacity, fill_color=fill_color,
                                       fill_opacity=fill_opacity, stroke_color=stroke_color,
                                       stroke_opacity=stroke_opacity, stroke_width=stroke_width).items()
                 if v is not None}
        self._make("svg_mobject", geom, dict(kwargs, **style), {}, n=None, extra=extra)


def _png_data_uri(pixels):
    """An image array (rows of [r, g, b(, a)] 0-255, or floats 0-1) as a PNG data URI."""
    import base64, struct, zlib
    rows = [list(_unarray(r)) for r in _unarray(pixels)]
    h, w = len(rows), len(rows[0]) if rows else 0

    def px(v):
        v = list(_unarray(v)) if hasattr(v, "__len__") or hasattr(v, "tolist") else [v, v, v]
        scale = 255.0 if all(isinstance(x, float) and x <= 1.0 for x in v) else 1.0
        v = [max(0, min(255, int(round(float(x) * scale)))) for x in v]
        return (v + [255])[:4] if len(v) >= 3 else [v[0], v[0], v[0], 255]

    raw = b"".join(b"\x00" + bytes(c for p in r for c in px(p)) for r in rows)

    def chunk(tag, data):
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    png = (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0))
           + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))
    return "data:image/png;base64," + base64.b64encode(png).decode("ascii")


def _own_attr(obj, name):
    """obj.name only if obj really has it: a JsRef answers every name with a lazy
    member (and records a command), so look without calling __getattr__."""
    found = inspect.getattr_static(obj, name, None)
    if found is None:
        return None
    return getattr(obj, name)


def _preview_object(v):
    """A JavaScript object in the browser page (a loaded or processed image, a canvas),
    or a wrapper holding one: its JsRef, else None."""
    if isinstance(v, _rt.JsRef):
        return v
    for name in ("_jsref", "ref", "handle"):
        x = _own_attr(v, name)
        if isinstance(x, _rt.JsRef):
            return x
    return None


_IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp", ".avif")


def _image_op_chain(ops=None, remove_background=False, resize=None):
    """Image ops run in the browser before the picture is used, in order:
    remove_background, then ops=[("name", {params}) …], then resize. The engine
    holds the commands after it until they are done, as it does for text."""
    chain = []
    if remove_background:
        chain.append(["remove_background", _j(remove_background) if isinstance(remove_background, dict) else {}])
    for op in ops or ():
        if isinstance(op, str):
            chain.append([op, {}])
        else:
            op = list(op)
            chain.append([str(op[0]), _j(op[1] if len(op) > 1 and op[1] else {})])
    if resize is not None:
        chain.append(["resize", _j(resize) if isinstance(resize, dict) else {"width": _num(resize)}])
    return chain


def _trace_params(trace):
    return _j(trace) if isinstance(trace, dict) else {}


class ImageMobject(Mobject):
    """A picture: a path beside the .py, a web address, a data URI, an array, or
    an image already in the browser page (load_image(...), and what image ops return).
    Optional rounded corners, a border, a shadow and a crop. Image ops run in the
    browser, no await needed: ops=[("remove_background",), ("resize", {"width": 800})],
    or remove_background=True, resize=800; trace=True (or {...}) makes it a vector
    outline instead."""

    def __init__(self, filename_or_array, scale_to_resolution=1080, invert=False, image_mode="RGBA",
                 corner_radius=0, border_color=None, border_width=0, shadow=None, crop=None, ops=None,
                 remove_background=False, resize=None, trace=None, **kwargs):
        # A Picture (pyctures_images) names its source: a relative path, or a blob:
        # URL for an image op's result.
        src = _own_attr(filename_or_array, "_cir_image_src") or filename_or_array
        ref = _preview_object(src)
        extra = ()
        if ref is not None:
            # The element itself travels as the call's 4th argument (the page
            # resolves a top-level {"$h": n} to the object).
            self._source = ref   # keeps the browser object alive
            src = None
            extra = ({"$h": ref._handle()},)
        elif not isinstance(src, str):
            src = _png_data_uri(src)
        # A relative path is sent as written: the app reads it from the file's folder.
        self.src = src
        chain = _image_op_chain(ops, remove_background, resize)
        if trace:
            # Traced to vector outlines (2Vec): an SVG object made from the picture.
            self._make("svg_mobject", {"image_src": src, "ops": chain, "trace": _trace_params(trace),
                                       "should_center": True, "height": None, "width": None},
                       kwargs, {}, n=None, extra=extra)
            return
        props = {"src": src, "scale_to_resolution": int(scale_to_resolution), "invert": bool(invert)}
        if chain:
            props["ops"] = chain
        self._make("image_mobject", props, kwargs, {}, n=0, extra=extra)
        if crop is not None:
            self.crop(*crop)
        if corner_radius:
            self.set_corner_radius(corner_radius)
        if border_color is not None or border_width:
            self.set_border(border_color or WHITE, border_width or DEFAULT_STROKE_WIDTH)
        if shadow:
            self.set_shadow(**(shadow if isinstance(shadow, dict) else {}))

    def set_corner_radius(self, radius):
        return self._op("set_corner_radius", {"radius": _num(radius)})

    def set_border(self, color=WHITE, width=DEFAULT_STROKE_WIDTH):
        return self._op("set_border", {"color": _color(color), "width": _num(width)})

    def crop(self, x0=0.0, y0=0.0, x1=1.0, y1=1.0):
        """Keep the box (x0, y0)–(x1, y1), as fractions of the picture, origin bottom-left."""
        return self._op("crop", {"box": [_num(x0), _num(y0), _num(x1), _num(y1)]})


