class ApplyMethod(Animation):
    """ApplyMethod(m.shift, UP): the method's change, played."""
    kind = "animate"

    def __init__(self, method, *args, **kwargs):
        timing = {k: kwargs.pop(k) for k in ("run_time", "rate_func", "lag_ratio") if k in kwargs}
        mob = method.__self__
        ops = []
        st = _st()
        prev = st.capture
        st.capture = (mob._t(), ops)
        try:
            method(*args, **kwargs)
        finally:
            st.capture = prev
        self._ops = ops
        Animation.__init__(self, mob, **timing)

    def _make_args(self, **kwargs):
        return {"ops": self._ops}


class ApplyFunction(Animation):
    """ApplyFunction(f, m): f's change to m, played."""
    kind = "animate"

    def __init__(self, function, mobject, **kwargs):
        ops = []
        st = _st()
        prev = st.capture
        st.capture = (mobject._t(), ops)
        try:
            result = function(mobject)
        finally:
            st.capture = prev
        if isinstance(result, Mobject) and result is not mobject:
            ops.append(["become", {"mobject": result._embed()}])
        self._ops = ops
        Animation.__init__(self, mobject, **kwargs)

    def _make_args(self, **kwargs):
        return {"ops": self._ops}


def _trace_formula(fn, args, what):
    tr, result, err = _run_trace(fn, args)
    if err is not None or result is None:
        raise TypeError("%s needs a function that can be worked out with + - * / and np.sin, np.cos … "
                        "(not math.* or an if on the point)%s" % (what, ": %s" % err if err else ""))
    return _tree(result)


